      final stopFuture = cubit.stopRecording();
      // Let `stopRecording()` reach `AudioProcessing` before leaving.
      await Future<void>.delayed(Duration.zero);
      expect(cubit.state, isA<AudioProcessing>());

      await cubit.cancel();
      expect(cubit.state, isA<AudioIdle>());

